// #3f693e Regression test — серверная защита company_profiles: משתמש רגיל (USER, компания A) не может писать профиль своей компании.
// Кейс: .qa/tests/permissions-isolation/PI-16. Supabase REST (PostgREST) от имени USER, мимо интерфейса.
// Секретов в тесте нет: apikey и токен берутся из запроса к Supabase, который сам сайт отправляет при открытии «/».
// Безопасность: PATCH/POST пишут только company_id = текущее значение; DELETE не используется. Состояние строки
// (updated_at и все поля) читает ADMIN компании A до и после и сравнивает.
// @data — идёт отдельно, по одному (обращается к данным общего аккаунта).
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';

type Creds = { url: string; apiKey: string; token: string; userId: string };

/** apikey и Bearer-токен — из первого запроса приложения к Supabase REST с токеном пользователя (не anon). */
async function credsFromAppRequest(page: Page): Promise<Creds> {
  const appRequest = page.waitForRequest((r) => {
    const h = r.headers();
    return /\.supabase\.co\/rest\/v1\//.test(r.url()) && !!h['apikey'] && /^Bearer /.test(h['authorization'] ?? '') && h['authorization'] !== `Bearer ${h['apikey']}`;
  });
  await page.goto('/');
  const req = await appRequest;
  const h = await req.allHeaders();
  const token = h['authorization'].replace(/^Bearer /, '');
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString());
  expect(payload.role, 'токен должен быть пользовательским (authenticated)').toBe('authenticated');
  return { url: new URL(req.url()).origin, apiKey: h['apikey'], token, userId: payload.sub };
}

const headers = (c: Creds, prefer?: string) => ({
  apikey: c.apiKey,
  Authorization: `Bearer ${c.token}`,
  'Content-Type': 'application/json',
  ...(prefer ? { Prefer: prefer } : {}),
});

async function companyIdOf(page: Page, c: Creds): Promise<string> {
  const res = await page.request.get(`${c.url}/rest/v1/company_members?select=company_id&user_id=eq.${c.userId}`, { headers: headers(c) });
  expect(res.status(), await res.text()).toBe(200);
  const rows: { company_id: string }[] = await res.json();
  expect(rows, 'пользователь должен состоять ровно в одной компании').toHaveLength(1);
  return rows[0].company_id;
}

test.describe('company_profiles בשרת — משתמש רגיל', () => {
  test('משתמש רגיל לא יכול לעדכן, להוסיף או לעשות upsert ל-company_profiles של החברה שלו; השורה לא השתנתה #3f693e @desktop @data', async ({ asUser }) => {
    const userPage = await asUser('user');
    const adminPage = await asUser('admin');
    const user = await credsFromAppRequest(userPage);
    const admin = await credsFromAppRequest(adminPage);
    const companyId = await companyIdOf(userPage, user);
    expect(await companyIdOf(adminPage, admin), 'ADMIN и USER — одна компания A').toBe(companyId);

    // Состояние строки до (читает ADMIN: у него есть право чтения профиля).
    const readRow = async () => {
      const res = await adminPage.request.get(`${admin.url}/rest/v1/company_profiles?select=*&company_id=eq.${companyId}`, { headers: headers(admin) });
      expect(res.status(), await res.text()).toBe(200);
      return (await res.json()) as Record<string, unknown>[];
    };
    const before = await readRow();
    expect(before, 'у компании A должна быть ровно одна строка профиля (иначе проверка 0 строк пустая)').toHaveLength(1);

    // 1. update: 200 и 0 строк (RLS profiles_update скрывает строку).
    const patch = await userPage.request.patch(`${user.url}/rest/v1/company_profiles?company_id=eq.${companyId}`, {
      headers: headers(user, 'return=representation'),
      data: { company_id: companyId },
    });
    const patchBody = await patch.text();
    expect(patch.status(), patchBody).toBe(200);
    expect(patchBody, 'БАГ: member изменил строку company_profiles').toBe('[]');

    // 2. insert: отказ RLS 403 / 42501 (profiles_insert требует is_company_admin).
    const insert = await userPage.request.post(`${user.url}/rest/v1/company_profiles`, {
      headers: headers(user, 'return=minimal'),
      data: { company_id: companyId },
    });
    const insertBody = await insert.text();
    expect(insert.status(), `ожидался 403; при 2xx/409 — БАГ. Ответ: ${insertBody}`).toBe(403);
    expect(insertBody).toContain('42501');

    // 3. upsert (merge-duplicates): тоже отказ 403 / 42501.
    const upsert = await userPage.request.post(`${user.url}/rest/v1/company_profiles?on_conflict=company_id`, {
      headers: headers(user, 'resolution=merge-duplicates,return=minimal'),
      data: { company_id: companyId },
    });
    const upsertBody = await upsert.text();
    expect(upsert.status(), `ожидался 403; при 2xx — БАГ. Ответ: ${upsertBody}`).toBe(403);
    expect(upsertBody).toContain('42501');

    // Строка не изменилась: все поля, включая updated_at, совпадают.
    expect(await readRow()).toEqual(before);
  });
});
